CREATE TABLE curated_place_menu (
    content_id VARCHAR(20) PRIMARY KEY,
    place_name VARCHAR(200) NOT NULL,
    source_label VARCHAR(100) NOT NULL,
    source_url VARCHAR(2000),
    verified_on DATE NOT NULL,
    verification_note VARCHAR(500)
);

CREATE TABLE curated_place_menu_item (
    menu_item_id BIGSERIAL PRIMARY KEY,
    content_id VARCHAR(20) NOT NULL REFERENCES curated_place_menu(content_id) ON DELETE CASCADE,
    menu_name VARCHAR(200) NOT NULL,
    price_won BIGINT,
    is_specialty BOOLEAN NOT NULL DEFAULT FALSE,
    image_url VARCHAR(2000),
    display_order INTEGER NOT NULL,
    CONSTRAINT uk_curated_place_menu_item UNIQUE (content_id, menu_name)
);

CREATE INDEX idx_curated_place_menu_item_content
    ON curated_place_menu_item(content_id, display_order);


